"use strict";

var _EnterpriseListTemplatesFilter = require("../EnterpriseListTemplatesFilter.utils");
describe('EnterpriseListTemplatesFilter.utils.js', function () {
  describe('removeDuplicatelistTemplatesById', function () {
    var mockListTemplateArray = [{
      id: '1337'
    }, {
      id: '1337'
    }, {
      id: '7357'
    }, {
      id: '7357'
    }];
    it('should return array of listTemplate Objects with duplicate ids removed ', function () {
      var valueReturned = (0, _EnterpriseListTemplatesFilter.removeDuplicatelistTemplatesById)(mockListTemplateArray);
      expect(valueReturned.length).toBe(2);
      expect(valueReturned).toEqual([{
        id: '1337'
      }, {
        id: '7357'
      }]);
    });
  });
});